window.COURSE = [{"id": 1, "title": "Modelado analítico avanzado", "focus": "Un indicador confiable empieza por una granularidad bien definida.", "goals": ["Distinguir línea de pedido y pedido.", "Relacionar dos hechos de diferente granularidad.", "Validar el cumplimiento sin duplicar metas."], "lessons": [["El contrato del dato", "En Ventas una fila es una línea de pedido; en Metas es mes y sucursal. Ingreso y Costo son importes totales por línea, en MXN sin IVA. La comparación debe respetar ese contrato."], ["Dimensiones compartidas", "DimSucursal y DimMes filtran tanto Ventas como Metas. DimProducto y DimFecha filtran solo Ventas. Configure relaciones 1 a varios, activas y con filtro único desde dimensiones hacia hechos. No conecte los hechos entre sí."], ["Dos escalas temporales", "Cree MesInicio en Ventas. DimMes se relaciona con MesInicio de ambos hechos; DimFecha con Fecha de Ventas. Mantenga ambas dimensiones independientes. Use DimMes para cumplimiento y DimFecha para detalle diario."], ["Riesgo de duplicación", "Al repetir una meta por cada línea, la suma incorrecta es 71000. La meta correcta es 48000. El cumplimiento pasa indebidamente de 93.75 % a 63.38 %. Un tablero convincente puede inducir una decisión equivocada."]], "code": [["Columna y calendario", "MesInicio = DATE(YEAR(Ventas[Fecha]), MONTH(Ventas[Fecha]), 1)\n\nDimFecha = CALENDAR(DATE(2026,1,1), DATE(2026,12,31))"], ["Medidas base", "Ingresos = SUM(Ventas[Ingreso])\n\nCostos = SUM(Ventas[Costo])\n\nUtilidad = [Ingresos] - [Costos]\n\nMargen = DIVIDE([Utilidad], [Ingresos])\n\nMeta mensual = SUM(Metas[Meta])\n\nPedidos = DISTINCTCOUNT(Ventas[PedidoID])"], ["Cumplimiento compatible", "Cumplimiento =\nIF(\n    ISCROSSFILTERED(DimProducto) || ISCROSSFILTERED(DimFecha),\n    BLANK(),\n    DIVIDE([Ingresos], [Meta mensual])\n)"]], "steps": ["Descargue Datos mínimos y cargue cada CSV como tabla con su nombre. Establezca fechas y claves con tipos compatibles.", "Cree MesInicio y DimFecha por separado: una columna y una tabla, respectivamente. Marque DimFecha como tabla de fechas usando Date.", "Relacione DimSucursal con ambos hechos por SucursalID; DimMes con ambos hechos por MesInicio; DimProducto con Ventas por ProductoID; DimFecha con Ventas por Fecha.", "Cree cada medida por separado. Construya una matriz con DimMes[AnioMes], DimSucursal[Sucursal], Ingresos, Meta mensual y Cumplimiento.", "Compruebe 45000 de ingresos, 28800 de costos, 16200 de utilidad, 36 % de margen, 5 pedidos y 93.75 % de cumplimiento.", "Filtre producto o fecha diaria: Cumplimiento debe quedar vacío. Esta protección supone ejes y filtros tomados de las dimensiones."], "delivery": "Un PBIX y un informe de dos páginas con captura del modelo, controles y explicación del error de metas. Rúbrica: granularidad 20, relaciones 25, medidas 25, diagnóstico 15 e interpretación 15 puntos.", "quiz": {"question": "En una matriz cada sucursal repite 45000. ¿Qué revisarías primero?", "options": ["La cantidad de decimales", "Que el campo del eje pertenezca a la dimensión relacionada y que la relación filtre Ventas", "El color del encabezado"], "answer": 1, "explain": "La dimensión desconectada o una relación incorrecta puede impedir que cada categoría filtre el hecho."}, "source": "https://learn.microsoft.com/power-bi/guidance/star-schema", "reading": "<h2>Modelado analítico avanzado para decisiones gerenciales</h2><p>Módulo 1 del curso Power BI avanzado</p><p>Guía de clase y práctica aplicada<br>Docente  Dra. Diana Rangel<br>Duración  3 horas guiadas y 2 horas de trabajo independiente</p><h3>Propósito del módulo</h3><p>Construir y auditar un modelo que compare ventas reales con metas sin duplicar importes ni presentar resultados en un nivel de detalle que los datos no permiten. La calidad del indicador depende de la definición del negocio y de las relaciones del modelo antes de depender de la fórmula DAX.</p><h3>Resultados de aprendizaje</h3><p>Declarar qué representa una fila en cada tabla y justificar su granularidad.</p><p>Diseñar dimensiones compartidas y dos tablas de hechos con distintos niveles de detalle.</p><p>Configurar relaciones y explicar cómo viajan los filtros.</p><p>Validar ingresos, margen y cumplimiento con cifras de control.</p><p>Identificar cuándo una comparación carece de una meta compatible.</p><h3>Caso de trabajo</h3><p>La empresa ficticia Horizonte Comercial opera las sucursales Norte y Sur. La dirección solicita evaluar el cumplimiento mensual y el margen. Ventas contiene líneas de pedido; Metas contiene un importe mensual por sucursal. Todos los datos son sintéticos, en pesos mexicanos, sin IVA y con costos totales por línea.</p><p>Pregunta para abrir la sesión: si el tablero muestra 110 % de cumplimiento, ¿qué comprobaría antes de autorizar un bono? El participante deberá justificar el periodo, la definición de ingreso y el nivel de detalle de la meta.</p><h3>Alcance</h3><p>Este módulo establece el modelo para el resto del curso. Las medidas DAX se emplean como instrumentos de validación; su evaluación detallada se desarrolla en los módulos siguientes. No se requiere publicar el informe para realizar la práctica.</p><h3>Secuencia de la sesión y conceptos críticos</h3><div class=\"table-scroll\"><table><tr><th>Bloque</th><th>Minutos</th><th>Actividad</th></tr><tr><td>Apertura y diagnóstico</td><td>15</td><td>Discutir el indicador de cumplimiento y sus supuestos</td></tr><tr><td>Diseño del modelo</td><td>40</td><td>Definir granularidad, claves y dimensiones</td></tr><tr><td>Caso de duplicación</td><td>20</td><td>Contrastar una combinación incorrecta con dos hechos</td></tr><tr><td>Descanso</td><td>10</td><td>Pausa</td></tr><tr><td>Laboratorio guiado</td><td>65</td><td>Cargar tablas, relacionar y construir medidas</td></tr><tr><td>Validación y debate</td><td>20</td><td>Contrastar resultados y discutir restricciones</td></tr><tr><td>Cierre</td><td>10</td><td>Explicar tarea y criterios de evaluación</td></tr></table></div><h3>Granularidad</h3><p>Es la definición exacta de una fila. En Ventas, una fila es una línea de pedido. En Metas, una fila es la combinación mes y sucursal. Declarar solo “datos de ventas” es insuficiente: un pedido puede contener varias líneas y no debe contarse como varios pedidos.</p><h3>Hechos y dimensiones</h3><p>Los hechos registran eventos o valores observados, como ingresos y costos. Las dimensiones describen los ejes de análisis, como producto, sucursal y fecha. La clave de una dimensión debe identificar una fila de manera única; la clave correspondiente puede repetirse en la tabla de hechos.</p><h3>Aditividad y porcentajes</h3><p>Ingresos y costos de este caso se pueden sumar entre líneas. El margen porcentual se calcula como utilidad total dividida entre ingreso total; no como promedio simple de los márgenes de cada línea. El inventario a una fecha es un ejemplo de saldo que no debe sumarse indiscriminadamente entre fechas.</p><h3>Filtros y ambigüedad</h3><p>La configuración inicial será uno a varios, con filtro único desde la dimensión hacia el hecho. Las relaciones bidireccionales requieren una necesidad explícita y validación de rutas; no deben utilizarse para ocultar claves duplicadas o relaciones mal definidas.</p><h3>Datos reproducibles del laboratorio</h3><p>En Power BI Desktop utilice Introducir datos y cree las siguientes cinco tablas con los nombres y columnas indicados. No agregue separadores de miles ni símbolos monetarios al capturar. Asigne tipo Fecha a las fechas; números enteros a las claves; decimal fijo a los importes. Las fechas se muestran en formato ISO año mes día.</p><h3>DimSucursal</h3><div class=\"table-scroll\"><table><tr><th>SucursalID</th><th>Sucursal</th></tr><tr><td>1</td><td>Norte</td></tr><tr><td>2</td><td>Sur</td></tr></table></div><h3>DimProducto</h3><div class=\"table-scroll\"><table><tr><th>ProductoID</th><th>Producto</th><th>Categoria</th></tr><tr><td>101</td><td>Equipo A</td><td>Equipos</td></tr><tr><td>102</td><td>Servicio B</td><td>Servicios</td></tr></table></div><h3>Ventas</h3><div class=\"table-scroll\"><table><tr><th>LineaID</th><th>PedidoID</th><th>Fecha</th><th>SucursalID</th><th>ProductoID</th><th>Ingreso</th><th>Costo</th></tr><tr><td>1</td><td>P01</td><td>2026-01-05</td><td>1</td><td>101</td><td>10000</td><td>7000</td></tr><tr><td>2</td><td>P01</td><td>2026-01-05</td><td>1</td><td>102</td><td>5000</td><td>2000</td></tr><tr><td>3</td><td>P02</td><td>2026-01-10</td><td>2</td><td>101</td><td>8000</td><td>6000</td></tr><tr><td>4</td><td>P03</td><td>2026-02-03</td><td>1</td><td>101</td><td>12000</td><td>8400</td></tr><tr><td>5</td><td>P04</td><td>2026-02-08</td><td>2</td><td>102</td><td>6000</td><td>2400</td></tr><tr><td>6</td><td>P05</td><td>2026-02-15</td><td>2</td><td>101</td><td>4000</td><td>3000</td></tr></table></div><h3>Metas</h3><div class=\"table-scroll\"><table><tr><th>MesInicio</th><th>SucursalID</th><th>Meta</th></tr><tr><td>2026-01-01</td><td>1</td><td>14000</td></tr><tr><td>2026-01-01</td><td>2</td><td>10000</td></tr><tr><td>2026-02-01</td><td>1</td><td>15000</td></tr><tr><td>2026-02-01</td><td>2</td><td>9000</td></tr></table></div><h3>DimMes</h3><div class=\"table-scroll\"><table><tr><th>MesInicio</th><th>AnioMes</th></tr><tr><td>2026-01-01</td><td>2026-01</td></tr><tr><td>2026-02-01</td><td>2026-02</td></tr></table></div><h3>Construcción y auditoría del modelo</h3><h3>Preparar la clave mensual de ventas</h3><p>En Ventas cree la columna calculada MesInicio y asígnele tipo Fecha. Mantenga Fecha como fecha diaria de operación.</p><p>MesInicio = DATE(YEAR(Ventas[Fecha]), MONTH(Ventas[Fecha]), 1)</p><h3>Paso 1 Crear la dimensión diaria</h3><p>Cree la tabla calculada DimFecha con un calendario de días continuos. Marque esta tabla como tabla de fechas y seleccione su columna Date. Compruebe que Fecha en Ventas no contenga una componente de hora.</p><p>DimFecha = CALENDAR(DATE(2026, 1, 1), DATE(2026, 12, 31))</p><p>Las fórmulas usan comas como separadores. Si su configuración regional requiere punto y coma, sustituya los separadores de argumentos.</p><h3>Paso 2 Configurar las relaciones</h3><p>Revise o elimine las relaciones detectadas automáticamente que contradigan esta lista. Todas las relaciones del laboratorio son activas, de uno a varios y con filtro único desde la primera tabla hacia la segunda.</p><div class=\"table-scroll\"><table><tr><th>Lado uno</th><th>Lado varios</th></tr><tr><td>DimSucursal[SucursalID]</td><td>Ventas[SucursalID]</td></tr><tr><td>DimSucursal[SucursalID]</td><td>Metas[SucursalID]</td></tr><tr><td>DimProducto[ProductoID]</td><td>Ventas[ProductoID]</td></tr><tr><td>DimMes[MesInicio]</td><td>Ventas[MesInicio]</td></tr><tr><td>DimMes[MesInicio]</td><td>Metas[MesInicio]</td></tr><tr><td>DimFecha[Date]</td><td>Ventas[Fecha]</td></tr></table></div><h3>Paso 3 Respetar el nivel de la meta</h3><p>No relacione Ventas directamente con Metas. DimMes permite filtrar ambas por meses completos. DimFecha filtra únicamente las ventas; una meta mensual no se convierte por ello en una meta diaria. No relacione DimMes con DimFecha en este diseño, para evitar dos rutas activas desde el mes hacia Ventas.</p><p>Para comparar cumplimiento utilice AnioMes de DimMes y Sucursal de DimSucursal. Reserve DimFecha para analizar ventas diarias. La práctica no distribuye metas por día ni por producto, porque no existe una regla de asignación aprobada.</p><h3>Paso 4 Controlar integridad y presentación</h3><p>Compruebe unicidad en cada dimensión y en la combinación MesInicio más SucursalID de Metas. Verifique que toda clave de Ventas y Metas exista en su dimensión. Oculte claves técnicas en la vista de informe y utilice los atributos de las dimensiones en ejes y filtros.</p><h3>Medidas y comprobaciones numéricas</h3><p>Cree cada expresión como una medida independiente. Aplique formato de moneda a ingresos, costos, utilidad y metas; porcentaje con dos decimales a margen y cumplimiento.</p><p>Ingresos = SUM(Ventas[Ingreso])<br><br>Costos = SUM(Ventas[Costo])<br><br>Utilidad = [Ingresos] - [Costos]<br><br>Margen = DIVIDE([Utilidad], [Ingresos])<br><br>Meta mensual = SUM(Metas[Meta])<br><br>Pedidos = DISTINCTCOUNT(Ventas[PedidoID])</p><h3>Evitar comparaciones fuera de alcance</h3><p>En este caso no existe meta por producto ni por día. La siguiente medida devuelve vacío si se utiliza cualquiera de esas dimensiones para filtrar. Es una protección específica para este modelo; si se incorporan nuevas dimensiones o filtros sobre los hechos, deberá revisarse.</p><p>Cumplimiento =<br>VAR NivelNoCompatible =<br>    ISCROSSFILTERED(DimProducto)<br>        || ISCROSSFILTERED(DimFecha)<br>RETURN<br>    IF(<br>        NivelNoCompatible,<br>        BLANK(),<br>        DIVIDE([Ingresos], [Meta mensual])<br>    )</p><h3>Cifras de control con DimMes y DimSucursal</h3><div class=\"table-scroll\"><table><tr><th>Periodo</th><th>Sucursal</th><th>Ingresos</th><th>Meta</th><th>Cumplimiento</th></tr><tr><td>2026-01</td><td>Norte</td><td>15000</td><td>14000</td><td>107.14 %</td></tr><tr><td>2026-01</td><td>Sur</td><td>8000</td><td>10000</td><td>80.00 %</td></tr><tr><td>2026-02</td><td>Norte</td><td>12000</td><td>15000</td><td>80.00 %</td></tr><tr><td>2026-02</td><td>Sur</td><td>10000</td><td>9000</td><td>111.11 %</td></tr><tr><td>Total</td><td>Ambas</td><td>45000</td><td>48000</td><td>93.75 %</td></tr></table></div><p>Controles adicionales sin filtros: costos 28800; utilidad 16200; margen 36.00 %; 6 líneas y 5 pedidos. Enero: ingresos 23000 y cumplimiento 95.83 %. Febrero: ingresos 22000 y cumplimiento 91.67 %.</p><p>No promedie los cuatro porcentajes para obtener el cumplimiento total. El total correcto es 45000 / 48000. Este conjunto es mínimo y sirve para auditar el modelo; no permite inferir tendencias, estacionalidad ni atípicos estadísticos.</p><h3>Práctica de diagnóstico y decisiones de diseño</h3><h3>Una meta duplicada cambia la decisión</h3><p>Si combina Metas con Ventas mediante mes y sucursal y después suma Meta, cada línea de venta recibe la meta completa. Norte en enero tiene dos líneas: la meta de 14000 se convierte artificialmente en 28000. Sur en febrero también tiene dos líneas: 9000 se convierte en 18000. El total incorrecto sería 71000 y el cumplimiento 63.38 %, frente al 93.75 % correcto.</p><p>Demostración opcional: en Power Query, cree una consulta de referencia de Ventas y combine con Metas usando ambas claves. Expanda Meta y compare la suma. Mantenga la consulta como prueba sin cargar al modelo y conserve las dos tablas de hechos originales.</p><h3>Diseños que requieren juicio avanzado</h3><div class=\"table-scroll\"><table><tr><th>Situación</th><th>Decisión y criterio</th></tr><tr><td>Fecha de pedido y fecha de entrega</td><td>Una fecha activa y otra inactiva pueden servir para medidas específicas. Si se requieren filtros simultáneos por ambos roles, considere dimensiones de fecha separadas.</td></tr><tr><td>Varios responsables por sucursal</td><td>Utilice una tabla puente si la relación real es de muchos a muchos; defina cómo evitar duplicar atribuciones.</td></tr><tr><td>Cambio de región de una sucursal</td><td>Defina si se informa con la región actual o histórica. El análisis histórico puede requerir versiones de dimensión con vigencia y claves sustitutas.</td></tr><tr><td>Meta mensual frente a ventas diarias</td><td>Compare meses completos o establezca una regla explícita de distribución diaria. No suponga una distribución uniforme.</td></tr></table></div><h3>Preguntas para el comité</h3><p>¿Qué evidencia permite confiar en el total de ventas y en la meta?</p><p>¿El cumplimiento de Sur en febrero significa que es la mejor sucursal? ¿Qué faltaría conocer sobre margen, capacidad y metas?</p><p>¿Es válido comparar una semana de ventas con una meta mensual completa?</p><p>¿Qué información adicional permitiría analizar metas por producto?</p><h3>Conclusión esperada</h3><p>El resultado global está 3000 por debajo de la meta. Norte cumple en enero y Sur en febrero. Estos resultados describen el caso; no demuestran causas ni justifican por sí solos decisiones sobre bonos o desempeño individual.</p><h3>Tarea y evaluación para Classroom</h3><h3>Texto de la tarea</h3><p>Título: Auditoría de un modelo de ventas y metas. Construya el modelo del caso Horizonte Comercial, valide sus resultados y explique cómo la granularidad condiciona los KPI. Utilice exclusivamente los datos sintéticos del módulo. Tiempo estimado de trabajo independiente: 2 horas.</p><p>Entregue un archivo Apellido_Modulo1.pbix y un informe de hasta dos páginas. El informe debe incluir la definición de una fila en cada hecho, una captura de relaciones, cifras de control, explicación del error de duplicación y una recomendación para la dirección con sus limitaciones.</p><p>En el informe de Power BI incluya una matriz mes por sucursal con ingresos, meta y cumplimiento; tarjetas de ingresos, utilidad y margen; y un gráfico de barras de ingresos por sucursal. Agregue una nota que indique que el cumplimiento se evalúa a nivel mensual y sucursal.</p><h3>Rúbrica de la tarea</h3><div class=\"table-scroll\"><table><tr><th>Criterio</th><th>Puntos</th><th>Evidencia para puntaje completo</th></tr><tr><td>Granularidad y definiciones</td><td>20</td><td>Declara correctamente las dos granularidades y la definición de los importes</td></tr><tr><td>Relaciones e integridad</td><td>25</td><td>Construye las seis relaciones y verifica claves y unicidad</td></tr><tr><td>Medidas y cifras de control</td><td>25</td><td>Reproduce todos los controles y protege el cumplimiento por día o producto</td></tr><tr><td>Diagnóstico del error</td><td>15</td><td>Explica por qué la meta incorrecta suma 71000 y cómo evitarlo</td></tr><tr><td>Interpretación ejecutiva</td><td>15</td><td>Presenta una recomendación coherente y reconoce límites de los datos</td></tr></table></div><p>Asignación parcial: otorgue aproximadamente la mitad de los puntos cuando el criterio esté incompleto pero sea conceptualmente correcto; cero cuando falte o se base en un error que invalida el resultado. La tarea se califica sobre 100 y forma parte de los retos del curso, no de una ponderación adicional.</p><h3>Organización del tema en Classroom</h3><p>Tema: 01 Modelado analítico avanzado. Material: esta guía. Tarea: instrucciones anteriores con la rúbrica. Pregunta de discusión: “¿Qué riesgo tiene evaluar a un gerente con una meta repetida por cada transacción?”. Publique las respuestas docentes después de la entrega. Configure la fecha límite según el calendario del curso.</p>", "quizzes": [{"question": "En una matriz cada sucursal repite 45000. ¿Qué revisarías primero?", "options": ["La cantidad de decimales", "Que el campo del eje pertenezca a la dimensión relacionada y que la relación filtre Ventas", "El color del encabezado"], "answer": 1, "explain": "La dimensión desconectada o una relación incorrecta puede impedir que cada categoría filtre el hecho."}, {"question": "P01 tiene dos líneas. ¿Qué expresión cuenta pedidos sin duplicarlos?", "options": ["COUNTROWS(Ventas)", "SUM(Ventas[LineaID])", "DISTINCTCOUNT(Ventas[PedidoID])"], "answer": 2, "explain": "El identificador del pedido puede repetirse por línea; se requiere conteo distinto."}, {"question": "La combinación de ventas y metas aumenta la meta de 48000 a 71000. ¿Qué pasó?", "options": ["La meta se repitió al expandir varias líneas por mes y sucursal", "Power BI cambió la moneda", "El segmentador redondeó el total"], "answer": 0, "explain": "La expansión repite importes cuando las tablas tienen diferente granularidad."}, {"question": "Power BI rechaza el lado uno de una relación. ¿Qué compruebas?", "options": ["Que todas las columnas sean medidas", "Que la clave de ese lado sea única y que los tipos coincidan", "Que el gráfico tenga título"], "answer": 1, "explain": "La clave del lado uno debe identificar una fila de la dimensión."}, {"question": "¿Qué dimensión del laboratorio debe filtrar ventas y metas mensuales?", "options": ["DimProducto", "DimFecha diaria", "DimMes"], "answer": 2, "explain": "DimMes es el eje compartido al nivel en el que se definieron las metas."}, {"question": "Aparece una categoría vacía aunque el catálogo no tiene textos vacíos. ¿Qué investigas?", "options": ["Claves del hecho sin correspondencia en la dimensión", "El tamaño del lienzo", "La fuente del título"], "answer": 0, "explain": "La integridad de claves puede generar una agrupación vacía en el modelo."}], "challenges": ["Provoca un total repetido usando una tabla de sucursales desconectada; explica y corrige el efecto.", "Demuestra con conteos la duplicación de metas al expandir una unión.", "Cambia el sentido del filtro solo en una copia y explica qué comportamiento observas."], "language": "dax", "resources": []}, {"id": 2, "title": "DAX y contexto de evaluación", "focus": "Comprender qué filas se evalúan antes de modificar una fórmula.", "goals": ["Diferenciar contexto de fila y de filtro.", "Explicar la transición de contexto.", "Recalcular proporciones en el total."], "lessons": [["Contexto de filtro", "Las filas, columnas, segmentadores y relaciones determinan el subconjunto que una medida evalúa. En una matriz, el total reevalúa la medida con otro contexto; no tiene por qué sumar las celdas visibles."], ["Contexto de fila", "Un iterador recorre una tabla y evalúa una expresión para cada fila. No equivale por sí mismo a filtrar otras tablas. Al invocar una medida dentro de un iterador, se produce transición de contexto implícita."], ["CALCULATE", "Evalúa una expresión modificando filtros y puede convertir contexto de fila en filtro. Un filtro sobre la misma columna suele sustituir el existente; KEEPFILTERS permite intersectarlo. Evite quitar filtros de toda la tabla sin una razón de negocio."], ["Medidas y columnas", "Una columna calculada se materializa al actualizar el modelo importado. Una medida se evalúa según el contexto de consulta. Las columnas sirven para clasificar o relacionar; las medidas para agregados dinámicos."]], "code": [["Iterador y denominador", "Utilidad iterada = SUMX(Ventas, Ventas[Ingreso] - Ventas[Costo])\n\nParticipacion sucursal =\nDIVIDE(\n    [Ingresos],\n    CALCULATE([Ingresos], REMOVEFILTERS(DimSucursal))\n)"], ["Intersección de filtros", "Ingresos Equipos =\nCALCULATE(\n    [Ingresos],\n    KEEPFILTERS(DimProducto[Categoria] = \"Equipos\")\n)"]], "steps": ["Conserve el modelo mínimo del módulo 1.", "Compare Utilidad iterada con Utilidad en todas las sucursales y meses. Deben coincidir.", "Cree una matriz por sucursal con Participacion sucursal: Norte 60 % y Sur 40 % sin otros filtros.", "Filtre categoría Servicios y evalúe Ingresos Equipos. La intersección queda sin filas.", "Explique el total del margen y por qué no se promedian porcentajes."], "delivery": "PBIX con tres pruebas de filtros y una explicación escrita de transición de contexto. Evalúe exactitud 50, pruebas 30 y explicación 20 puntos.", "quiz": {"question": "El margen total no coincide con el promedio de las filas. ¿Es siempre un error?", "options": ["Sí: todo total debe promediar filas", "No: la medida se reevalúa con utilidad total e ingreso total", "Sí: se corrige sumando porcentajes"], "answer": 1, "explain": "El total tiene otro contexto y debe conservar la definición de margen."}, "source": "https://learn.microsoft.com/es-es/dax/calculate-function-dax", "quizzes": [{"question": "El margen total no coincide con el promedio de las filas. ¿Es siempre un error?", "options": ["Sí: todo total debe promediar filas", "No: la medida se reevalúa con utilidad total e ingreso total", "Sí: se corrige sumando porcentajes"], "answer": 1, "explain": "El total tiene otro contexto y debe conservar la definición de margen."}, {"question": "¿Qué ocurre al formatear 0.9375 como porcentaje?", "options": ["Se muestra 0.9375 %", "Se muestra 9375 %", "Se muestra 93.75 %"], "answer": 2, "explain": "El formato porcentual escala la representación; no hay que multiplicar antes por 100."}, {"question": "Una columna calculada debe cambiar con cada segmentador. ¿Qué usarías en su lugar para un agregado dinámico?", "options": ["Una medida", "Una columna con otro color", "Una relación muchos a muchos"], "answer": 0, "explain": "Las medidas se evalúan según el contexto del informe; las columnas importadas se calculan al actualizar."}, {"question": "¿Qué hace REMOVEFILTERS(DimSucursal) en el denominador de participación?", "options": ["Elimina filas del archivo", "Quita el filtro de sucursal durante esa evaluación y conserva los demás filtros aplicables", "Borra los segmentadores de la página"], "answer": 1, "explain": "Es un cambio de contexto dentro de la medida, no una edición del informe ni de la fuente."}, {"question": "Filtras Servicios y aplicas KEEPFILTERS(Categoria=\"Equipos\"). ¿Qué esperas?", "options": ["Siempre Equipos", "Siempre Servicios", "La intersección puede quedar sin filas"], "answer": 2, "explain": "KEEPFILTERS intersecta la condición con el filtro existente."}, {"question": "SUMX(Ventas, Ingreso-Costo) devuelve la utilidad correcta. ¿Qué recorre?", "options": ["Las filas de Ventas visibles en el contexto", "Solo los totales del gráfico", "Todos los archivos de la computadora"], "answer": 0, "explain": "SUMX evalúa la expresión por fila del conjunto filtrado y suma los resultados."}], "challenges": ["Predice el margen total antes de mostrarlo y compruébalo con importes.", "Compara una condición con y sin KEEPFILTERS bajo un filtro incompatible.", "Construye una medida que quite solo el filtro de sucursal y conserva el mes."], "language": "dax", "resources": []}, {"id": 3, "title": "Filtros avanzados y parámetros con DAX", "focus": "Controla lo que cambia con los segmentadores, rankings y tablas desconectadas.", "goals": ["Construir un ranking que respete selecciones.", "Distinguir ALLSELECTED de quitar todos los filtros.", "Aplicar TREATAS con una tabla desconectada."], "lessons": [["Ranking", "RANKX evalúa la expresión por cada elemento de una tabla. Defina universo, dirección y tratamiento de empates. Un ranking entre sucursales seleccionadas responde una pregunta distinta de uno entre todas las sucursales."], ["Tablas virtuales", "VALUES devuelve los elementos del contexto. ADDCOLUMNS puede enriquecer una tabla temporal y TOPN seleccionar los primeros resultados. TOPN puede devolver más de N filas cuando hay empate en el límite."], ["Filtro virtual", "TREATAS proyecta valores de una tabla hacia columnas de otra. Úselo cuando no corresponda una relación física. Documente claves, tipos y valores sin correspondencia; no es una solución genérica para relaciones defectuosas."]], "code": [["Ranking seleccionado", "Ranking ingresos =\nIF(\n    ISINSCOPE(DimSucursal[Sucursal]),\n    RANKX(ALLSELECTED(DimSucursal[Sucursal]), [Ingresos], , DESC, DENSE)\n)"], ["Selector sin relación", "SelectorSucursal = SELECTCOLUMNS(\n    DimSucursal, \"SucursalID\", DimSucursal[SucursalID],\n    \"Sucursal\", DimSucursal[Sucursal]\n)\n\nIngresos seleccion virtual =\nCALCULATE(\n    [Ingresos],\n    KEEPFILTERS(TREATAS(VALUES(SelectorSucursal[SucursalID]), DimSucursal[SucursalID]))\n)"]], "steps": ["Use Datos extendidos en una copia nueva del PBIX. Sustituya las cinco tablas, sin mezclar juegos de datos.", "Repita el modelo del módulo 1 y cambie el calendario a 2024-01-01 hasta 2025-12-31.", "Cree SelectorSucursal como tabla calculada sin relaciones.", "Construya el ranking y filtre dos sucursales; observe cómo cambia el universo.", "Seleccione una sucursal en SelectorSucursal y valide el ingreso contra un filtro físico equivalente."], "delivery": "Ranking, selector virtual y una nota con la población comparada. Evalúe filtros 40, ranking 30 y validación 30.", "quiz": {"question": "Seleccionas dos sucursales y quieres ranking solo entre ellas. ¿Qué tabla usarías como universo?", "options": ["ALLSELECTED de la columna de sucursal", "Todas las ventas sin ningún filtro", "Una columna de colores"], "answer": 0, "explain": "ALLSELECTED puede conservar la selección externa para construir el universo visible."}, "source": "https://learn.microsoft.com/dax/treatas-function-dax", "quizzes": [{"question": "Seleccionas dos sucursales y quieres ranking solo entre ellas. ¿Qué tabla usarías como universo?", "options": ["ALLSELECTED de la columna de sucursal", "Todas las ventas sin ningún filtro", "Una columna de colores"], "answer": 0, "explain": "ALLSELECTED puede conservar la selección externa para construir el universo visible."}, {"question": "Un segmentador de una tabla sin relaciones no afecta Ingresos. ¿Qué falta?", "options": ["Cambiarlo a lista desplegable", "Una medida que aplique su selección, por ejemplo con TREATAS", "Ordenarlo alfabéticamente"], "answer": 1, "explain": "Una tabla desconectada no propaga filtros físicamente por sí sola."}, {"question": "TOPN(3, ...) devuelve cuatro filas con un empate en el límite. ¿Qué revisas?", "options": ["Que el ordenador tenga más memoria", "La configuración de moneda", "El tratamiento de empates y los criterios de orden"], "answer": 2, "explain": "TOPN puede devolver más de N filas cuando hay empates en el límite."}, {"question": "TREATAS proyecta claves que no existen en la dimensión. ¿Debes asumir que crea esas claves?", "options": ["No: hay que revisar las correspondencias de valores", "Sí: agrega filas al catálogo", "Sí: crea una relación física"], "answer": 0, "explain": "TREATAS aplica filtros virtuales; no modifica las tablas ni inserta claves faltantes."}, {"question": "El ranking aparece como 1 también en el total. ¿Cómo puedes ocultarlo en ese nivel?", "options": ["Con una fuente más pequeña", "Comprobando el nivel con ISINSCOPE", "Convirtiéndolo a texto fijo"], "answer": 1, "explain": "ISINSCOPE permite decidir si la medida debe mostrarse en el nivel de agrupación esperado."}, {"question": "Quieres que un parámetro desconectado cambie entre dos medidas. ¿Qué patrón encaja?", "options": ["Cambiar el nombre de la página", "Eliminar las relaciones", "SELECTEDVALUE más SWITCH en una medida"], "answer": 2, "explain": "Una medida puede leer la selección y elegir una expresión. La tabla de parámetro no necesita relación física."}], "challenges": ["Compara ranking global y ranking entre seleccionadas en una misma matriz.", "Desconecta un selector y hazlo funcionar mediante una medida, sin crear relación.", "Crea un empate y observa cuántas filas devuelve TOPN."], "language": "dax", "resources": []}, {"id": 4, "title": "Inteligencia de tiempo", "focus": "Comparar periodos equivalentes y controlar calendarios incompletos.", "goals": ["Construir variación interanual.", "Calcular acumulados y ventanas móviles.", "Detectar comparaciones parciales."], "lessons": [["Calendario", "Utilice DimFecha continua y marque Date como columna de fechas. Para este laboratorio se usa el calendario extendido 2024–2025. Agregue Anio, MesNumero y AnioMes en DimFecha si necesita ejes; ordene los nombres de mes por su número."], ["Evitar la doble restricción", "En este modelo DimMes también filtra Ventas. Las medidas temporales siguientes quitan DimMes y trabajan con DimFecha. Use ejes y segmentadores de DimFecha para este análisis; el módulo de cumplimiento sigue usando DimMes."], ["Periodos equivalentes", "Comparar el mes en curso parcial con un mes anterior completo produce una conclusión sesgada. Declare fecha de corte y compare los mismos días o use meses cerrados. El crecimiento sobre un denominador cero no tiene un porcentaje interpretable."], ["Ventanas móviles", "Un acumulado anual responde cuánto se ha logrado desde enero; una ventana móvil responde cuánto se ha logrado en los últimos N meses. No son intercambiables y el borde inicial puede contener menos meses de historia."]], "code": [["Base temporal y año anterior", "Ingresos tiempo = CALCULATE([Ingresos], REMOVEFILTERS(DimMes))\n\nIngresos AA = CALCULATE(\n    [Ingresos tiempo], SAMEPERIODLASTYEAR(DimFecha[Date])\n)\n\nVariacion interanual =\nDIVIDE([Ingresos tiempo] - [Ingresos AA], [Ingresos AA])"], ["Acumulado y ventana", "Ingresos YTD = TOTALYTD([Ingresos tiempo], DimFecha[Date])\n\nIngresos 12M =\nCALCULATE(\n    [Ingresos tiempo],\n    DATESINPERIOD(DimFecha[Date], MAX(DimFecha[Date]), -12, MONTH)\n)"]], "steps": ["Use el conjunto extendido y el calendario 2024–2025.", "Cree las cuatro medidas temporales y una línea por DimFecha[Date] agregada a mes.", "Compare enero de 2025 con enero de 2024 y valide mediante sumas de la fuente.", "Explique por qué enero de 2024 carece de año anterior disponible.", "Compare YTD y 12M en junio de 2025. Documente el efecto de la fecha de corte."], "delivery": "Página temporal con fecha de corte y una validación manual. Evalúe comparabilidad 40, medidas 40 y comunicación 20.", "quiz": {"question": "El eje usa solo nombre de mes y mezcla enero de 2024 y 2025. ¿Qué falta?", "options": ["Un color por barra", "Una clave o etiqueta que distinga año y mes", "Más decimales"], "answer": 1, "explain": "El nivel mensual debe identificar también el año cuando existen varios años."}, "source": "https://learn.microsoft.com/dax/datesinperiod-function-dax", "quizzes": [{"question": "El eje usa solo nombre de mes y mezcla enero de 2024 y 2025. ¿Qué falta?", "options": ["Un color por barra", "Una clave o etiqueta que distinga año y mes", "Más decimales"], "answer": 1, "explain": "El nivel mensual debe identificar también el año cuando existen varios años."}, {"question": "La medida del año anterior queda vacía en 2024 con datos desde 2024. ¿Es razonable?", "options": ["No: debería inventar 2023", "No: debe repetir 2024", "Sí: no hay hechos de 2023 disponibles"], "answer": 2, "explain": "La comparación requiere historia real o datos de referencia, no repetir el periodo actual."}, {"question": "¿Por qué las medidas temporales del laboratorio quitan DimMes?", "options": ["Para evitar que el mes del modelo limite también la búsqueda del periodo desplazado", "Para borrar el calendario", "Para convertir fechas a texto"], "answer": 0, "explain": "DimMes y DimFecha pueden imponer dos restricciones sobre Ventas; el ejemplo trabaja con la dimensión diaria."}, {"question": "¿Qué debe tener una tabla de fechas usada para estas expresiones?", "options": ["Una fila por operación", "Una secuencia continua de fechas únicas para el rango requerido", "Una fecha repetida por sucursal"], "answer": 1, "explain": "La dimensión diaria del ejercicio identifica cada día una sola vez y cubre el rango."}, {"question": "En junio de 2025, YTD y 12M difieren. ¿Qué periodo suma cada uno?", "options": ["Ambos solo junio", "YTD 12 meses y 12M solo enero a junio", "YTD desde enero; 12M una ventana móvil de doce meses"], "answer": 2, "explain": "Son ventanas distintas y por eso sus resultados no tienen que coincidir."}, {"question": "La línea mensual queda ordenada abril, agosto, diciembre. ¿Qué pasó?", "options": ["Se ordenó una etiqueta de texto alfabéticamente", "Power BI eliminó los meses", "La medida sumó costos"], "answer": 0, "explain": "Ordene por una fecha de inicio de mes o una clave cronológica adecuada."}], "challenges": ["Cambia la fecha a jerarquía automática y después a fecha simple; documenta la diferencia.", "Muestra dos eneros de años distintos sin mezclarlos.", "Prueba el año anterior con y sin filtro de DimMes y explica el resultado."], "language": "dax", "resources": []}, {"id": 5, "title": "Tarjetas KPI y formato condicional", "focus": "Construye tarjetas, metas, semáforos y títulos que respondan a los filtros.", "goals": ["Configurar tarjetas y referencias de meta.", "Aplicar colores mediante una medida.", "Distinguir la tarjeta del visual KPI."], "lessons": [["Tarjeta y visual KPI", "Una tarjeta presenta una medida y puede incluir referencias según la versión del visual. El visual KPI utiliza un indicador, una referencia de objetivo y un eje de tendencia; revise qué punto temporal se está mostrando. No asuma que todo visual que dice KPI calcula el total del periodo."], ["Configuración práctica", "En una página de cumplimiento use DimMes y DimSucursal. Agregue tarjetas de Ingresos, Meta mensual y Cumplimiento. Ajuste unidades y decimales por visual. Un porcentaje DAX como 0.9375 se formatea como 93.75 %; no multiplique por 100 y después aplique porcentaje."], ["Color por valor de campo", "Cree Color cumplimiento y, donde el visual admita fx, seleccione formato por valor de campo y la medida de color. Agregue también una etiqueta de estado: el color no debe ser la única explicación."], ["Pruebas de contexto", "Filtre mes, sucursal y producto. El cumplimiento del modelo devuelve vacío por producto porque no existe meta con esa granularidad. Mantenga el vacío y muestre una etiqueta explicativa en lugar de inventar un cero."]], "code": [["Color hexadecimal", "Color cumplimiento =\nVAR C = [Cumplimiento]\nRETURN SWITCH(TRUE(),\n    ISBLANK(C), \"#667085\",\n    C >= 1, \"#18724A\",\n    C >= 0.9, \"#9A6700\",\n    \"#B42318\"\n)"], ["Etiqueta y título", "Etiqueta cumplimiento =\nVAR C = [Cumplimiento]\nRETURN SWITCH(TRUE(),\n    ISBLANK(C), \"Sin meta compatible\",\n    C >= 1, \"Meta alcanzada\",\n    C >= 0.9, \"En tolerancia\",\n    \"Fuera de tolerancia\"\n)\n\nTitulo ventas =\n\"Ventas | \" & SELECTEDVALUE(DimSucursal[Sucursal], \"Varias sucursales\")"]], "steps": ["Use el modelo extendido a partir del módulo 3.", "Cree tres tarjetas: Ingresos, Meta mensual y Cumplimiento, con unidades consistentes.", "Configure el color por valor de campo donde esté disponible y agregue Etiqueta cumplimiento.", "En las propiedades de título use fx y Titulo ventas si el visual permite valor de campo.", "Pruebe Norte en enero de 2026 con el modelo mínimo para verificar 107.14 %; no mezcle ese control con el modelo extendido.", "En un visual KPI separado use una medida temporal y un eje de DimFecha. Compare el valor del último punto con una tarjeta del total."], "delivery": "PBIX con tarjetas, colores por medida y tres capturas con filtros distintos. Se evalúa configuración 40, respuesta a filtros 35 y consistencia de formato 25.", "quiz": {"question": "Una tarjeta muestra 9375 % en lugar de 93.75 %. ¿Qué revisarías?", "options": ["Si multiplicaste por 100 antes de aplicar formato porcentaje", "El zoom del lienzo", "La orientación de la página"], "answer": 0, "explain": "Una doble escala provoca ese resultado: conserve el cociente y aplique formato."}, "source": "https://learn.microsoft.com/power-bi/create-reports/desktop-conditional-table-formatting", "language": "dax", "quizzes": [{"question": "Una tarjeta muestra 9375 % en lugar de 93.75 %. ¿Qué revisarías?", "options": ["Si multiplicaste por 100 antes de aplicar formato porcentaje", "El zoom del lienzo", "La orientación de la página"], "answer": 0, "explain": "Una doble escala provoca ese resultado: conserve el cociente y aplique formato."}, {"question": "Una tarjeta de total y un visual KPI con tendencia no coinciden. ¿Qué revisas primero?", "options": ["La conexión a GitHub", "El contexto y el punto temporal que usa el KPI", "La fuente del título"], "answer": 1, "explain": "El KPI con eje temporal puede representar el último punto, mientras la tarjeta evalúa otro contexto."}, {"question": "Una medida devuelve \"#18724A\". ¿Cómo la aplicas como color donde el visual lo admita?", "options": ["Como relación", "Como fecha", "Con formato condicional por valor de campo"], "answer": 2, "explain": "El valor hexadecimal puede alimentar la propiedad de color mediante fx."}, {"question": "La tarjeta dice 45 mil y la tabla 45000. ¿Son necesariamente distintos?", "options": ["No: pueden ser distintas unidades de presentación del mismo valor", "Sí: siempre se perdieron filas", "Sí: hay duplicados"], "answer": 0, "explain": "Revise las unidades de visualización antes de buscar un error en el modelo."}, {"question": "Filtrar un producto deja Cumplimiento vacío en este caso. ¿Qué mostrarías?", "options": ["Cero como si fuera incumplimiento", "Una etiqueta de meta no compatible con ese nivel", "100 % para evitar vacíos"], "answer": 1, "explain": "El vacío preserva la falta de denominador compatible."}, {"question": "El título debe cambiar con la sucursal seleccionada. ¿Qué usarías?", "options": ["Una imagen fija", "Un texto escrito a mano por cada filtro", "Una medida de texto y fx si el título lo admite"], "answer": 2, "explain": "Un título basado en medida puede responder al contexto sin editarlo manualmente."}], "challenges": ["Provoca el error9375 % y corrígelo sin cambiar el dato de origen.", "Cambia la sucursal y demuestra que título, tarjeta y color usan el mismo contexto.", "Construye tarjeta y KPI temporal y explica cualquier diferencia de valor."], "resources": []}, {"id": 6, "title": "Power Query y actualización de archivos", "focus": "Combina archivos y diagnostica los pasos que rompen una actualización.", "goals": ["Distinguir combinar consultas y anexar consultas.", "Controlar tipos y configuración regional.", "Preparar una carga reproducible desde carpeta."], "lessons": [["Anexar y combinar", "Anexar apila filas y alinea columnas por nombre; combinar agrega columnas utilizando claves. Al combinar con una tabla de claves repetidas, una fila puede expandirse varias veces. Revise conteos antes y después de expandir."], ["Pasos y errores", "Los pasos se ejecutan en orden. Renombrar o quitar una columna puede romper un paso posterior. Los errores de conversión no son equivalentes a valores nulos: inspecciónelos antes de reemplazarlos."], ["Configuración regional", "Una cadena 1,234 puede significar mil doscientos treinta y cuatro o un decimal según el origen. Convierta con la configuración regional correcta. No elimine comas o puntos indiscriminadamente; conserve la fuente para poder auditar."], ["Desde carpeta", "El conector de carpeta permite transformar y anexar archivos de estructura comparable. Filtre extensión y archivos temporales antes de combinar, y revise el archivo de ejemplo. Un CSV con columnas diferentes puede cambiar la salida o fallar en los pasos posteriores."], ["Aplicar y actualizar", "Cerrar y aplicar carga transformaciones al modelo. Actualizar vuelve a consultar las fuentes. Una ruta local que funciona en Desktop necesita una estrategia de acceso en el servicio; no prometa actualización automática solo porque el PBIX se publicó."]], "code": [["Ejemplo M con ruta a sustituir", "let\n    Origen = Csv.Document(\n        File.Contents(\"C:\\CURSO\\Ventas.csv\"),\n        [Delimiter=\",\", Encoding=65001, QuoteStyle=QuoteStyle.Csv]\n    ),\n    Encabezados = Table.PromoteHeaders(Origen, [PromoteAllScalars=true]),\n    Tipos = Table.TransformColumnTypes(Encabezados,\n        {{\"Fecha\", type date}, {\"Ingreso\", type number}, {\"Costo\", type number}},\n        \"en-US\"\n    )\nin\n    Tipos"]], "steps": ["En una copia de práctica, entre en Transformar datos y duplique Ventas.", "Filtre una copia a 2024 y otra a 2025; anexe y compruebe que recupera las 4608 filas originales. No anexe la tabla completa otra vez.", "Combine DimSucursal con un catálogo de cuatro claves únicas y compruebe que la expansión no aumenta filas.", "Duplique una clave del catálogo de prueba, repita la combinación y explique el aumento.", "Pruebe texto de fecha e importe con dos configuraciones regionales y documente la correcta para cada fuente.", "Cree una carpeta de prueba con dos archivos de igual esquema y configure la combinación. Mantenga ese laboratorio separado del modelo del curso."], "delivery": "Consultas de práctica, conteos antes y después y bitácora de tipos. Evaluación: transformación 40, controles 40 y actualización 20.", "quiz": {"question": "Tienes doce archivos mensuales con las mismas columnas. ¿Qué operación apila sus registros?", "options": ["Combinar por clave", "Anexar consultas", "Crear una relación"], "answer": 1, "explain": "Anexar coloca filas unas debajo de otras; combinar incorpora columnas mediante una unión."}, "source": "https://learn.microsoft.com/power-query/merge-queries-overview", "language": "powerquery", "quizzes": [{"question": "Tienes doce archivos mensuales con las mismas columnas. ¿Qué operación apila sus registros?", "options": ["Combinar por clave", "Anexar consultas", "Crear una relación"], "answer": 1, "explain": "Anexar coloca filas unas debajo de otras; combinar incorpora columnas mediante una unión."}, {"question": "Después de expandir una combinación se duplican filas. ¿Qué comprobarías?", "options": ["Que la columna derecha de unión tenga claves repetidas", "Que el fondo sea claro", "Que el título sea corto"], "answer": 0, "explain": "Cada correspondencia del lado derecho puede expandir la fila izquierda."}, {"question": "Un importe 1,234 se interpreta distinto según el origen. ¿Qué debes definir?", "options": ["Un tamaño de tarjeta", "Un marcador", "El tipo y la configuración regional de conversión"], "answer": 2, "explain": "La conversión debe corresponder al formato real del archivo."}, {"question": "Quitaste una columna y ahora falla un paso posterior. ¿Dónde investigas?", "options": ["En el color de la visual", "En Pasos aplicados y las referencias a esa columna", "En el nombre del curso"], "answer": 1, "explain": "Los pasos posteriores pueden depender de una columna eliminada."}, {"question": "El modelo funciona con C:\\CURSO\\Ventas.csv en Desktop. ¿Se actualizará en el servicio sin configurar nada?", "options": ["Sí, siempre", "Sí, si el gráfico es pequeño", "No necesariamente: hay que resolver acceso a la fuente y credenciales"], "answer": 2, "explain": "La ruta local no otorga por sí misma acceso al servicio."}, {"question": "Anexas la tabla completa a sus dos mitades 2024 y 2025. ¿Qué provocas?", "options": ["Duplicación de las filas ya incluidas", "Una relación nueva", "Solo cambios de formato"], "answer": 0, "explain": "Las mitades ya reconstruyen el total; anexar además el total lo duplica."}], "challenges": ["Introduce una clave duplicada a la derecha de una combinación y anticipa el nuevo conteo.", "Cambia el nombre de una columna antes de un paso dependiente y repara el error.", "Procesa una fecha y un importe con dos configuraciones regionales."], "resources": []}, {"id": 7, "title": "Detección de datos atípicos", "focus": "Evaluar observaciones extremas dentro de poblaciones comparables.", "goals": ["Aplicar IQR y analizar sensibilidad.", "Distinguir IQR, Z y MAD.", "Investigar sin eliminar automáticamente."], "lessons": [["Población de referencia", "Compare operaciones con misma moneda, unidad, producto y periodo relevante. Mezclar servicios pequeños y equipos grandes puede etiquetar como extremos valores normales. El resultado depende de la población y de los filtros."], ["Tres enfoques", "IQR usa Q1 y Q3: límites Q1−1.5×IQR y Q3+1.5×IQR. Z=(x−media)/desviación y un umbral como |Z|>3 es una heurística, no una ley universal. MAD es la mediana de |x−mediana|; una puntuación robusta usual es 0.6745×(x−mediana)/MAD. Si la dispersión es cero, no divida."], ["Estrategia DAX", "En esta práctica cree una tabla de referencia con ALLSELECTED(Ventas) y calcule percentiles por sucursal y producto. La población mantiene las selecciones externas y retira el filtro de la operación de la visual. Inspeccione el número de operaciones antes de interpretar."], ["Decisión posterior", "Una observación marcada inicia una revisión de captura, contrato, promoción y operación. Conserve la señal original y documente el motivo de cualquier exclusión. No trate un valor atípico como fraude demostrado."]], "code": [["Bandera IQR por operación", "Atipico IQR =\nVAR S = SELECTEDVALUE(Ventas[SucursalID])\nVAR P = SELECTEDVALUE(Ventas[ProductoID])\nVAR X = SELECTEDVALUE(Ventas[Ingreso])\nVAR Ref = FILTER(\n    ALLSELECTED(Ventas),\n    Ventas[SucursalID] = S && Ventas[ProductoID] = P\n)\nVAR Q1 = PERCENTILEX.INC(Ref, Ventas[Ingreso], 0.25)\nVAR Q3 = PERCENTILEX.INC(Ref, Ventas[Ingreso], 0.75)\nVAR I = Q3 - Q1\nRETURN\nIF(\n    NOT HASONEVALUE(Ventas[LineaID]) || COUNTROWS(Ref) < 20 || I = 0,\n    BLANK(),\n    IF(X < Q1 - 1.5 * I || X > Q3 + 1.5 * I, 1, 0)\n)"]], "steps": ["Use Datos extendidos y una tabla visual con LineaID, SucursalID, ProductoID e Ingreso de Ventas.", "Agregue Atipico IQR como medida y filtre la visual a valor 1.", "Busque la operación inyectada en Centro, Servicio D, septiembre de 2025. No suponga que será la única marcada.", "Cambie el rango temporal mediante DimFecha y compare las banderas: la población de referencia cambia.", "Calcule Q1 y Q3 para una población seleccionada en una herramienta independiente y contraste resultados. El mínimo de 20 es una regla didáctica, no una garantía estadística."], "delivery": "Listado revisable de operaciones marcadas, población y dos verificaciones. Evalúe población 35, cálculos 35 e interpretación 30.", "quiz": {"question": "La bandera IQR se calcula sobre cinco operaciones. ¿Qué limita la práctica?", "options": ["El tema de colores", "El tamaño y estabilidad de la población de referencia", "El nombre de la sucursal"], "answer": 1, "explain": "Con pocos valores la referencia es frágil; el código establece un mínimo didáctico."}, "source": "https://learn.microsoft.com/dax/percentilex-inc-function-dax", "quizzes": [{"question": "La bandera IQR se calcula sobre cinco operaciones. ¿Qué limita la práctica?", "options": ["El tema de colores", "El tamaño y estabilidad de la población de referencia", "El nombre de la sucursal"], "answer": 1, "explain": "Con pocos valores la referencia es frágil; el código establece un mínimo didáctico."}, {"question": "¿Por qué la medida IQR exige una sola LineaID en el contexto?", "options": ["Porque clasifica una operación individual", "Para cambiar el color del mapa", "Porque no puede usar medidas"], "answer": 0, "explain": "El valor que se contrasta debe corresponder a una operación, no a un agregado ambiguo."}, {"question": "Cambias el segmentador de fecha y algunas banderas cambian. ¿Qué puede explicarlo?", "options": ["Las operaciones se borraron del CSV", "El tema modificó importes", "Cambió la población seleccionada usada para los percentiles"], "answer": 2, "explain": "La referencia del ejemplo responde a las selecciones externas."}, {"question": "IQR vale cero. ¿Debes forzar un cálculo como si hubiera dispersión?", "options": ["Sí, siempre", "No: documenta el caso y utiliza una regla compatible", "Sí: divide entre cero"], "answer": 1, "explain": "Una población sin dispersión por cuartiles exige revisar la regla de clasificación."}, {"question": "El total de Atipico IQR aparece vacío. ¿Es coherente con la medida?", "options": ["Sí: el total no identifica una sola operación", "No: debería sumar por sí solo", "No: el total debe ser siempre uno"], "answer": 0, "explain": "La medida devuelve vacío fuera del nivel individual; contar marcadas requiere otra expresión."}, {"question": "Una operación es marcada como extrema. ¿Qué acción está justificada?", "options": ["Borrarla automáticamente", "Confirmar fraude", "Revisar fuente, contexto y motivo antes de corregir o excluir"], "answer": 2, "explain": "Una regla estadística inicia una investigación; no determina su causa."}], "challenges": ["Explica antes de probar qué filtros alterarán la referencia IQR.", "Demuestra que el total vacío de la bandera es un comportamiento intencional.", "Compara un mes y un año como referencia para el mismo producto."], "language": "dax", "resources": []}, {"id": 8, "title": "Crear diseños y ubicar visuales con coordenadas", "focus": "Construye una página de 1280 × 720 usando X, Y, ancho y alto.", "goals": ["Diseñar una retícula que pueda reproducirse.", "Ubicar visuales por coordenadas del lienzo.", "Aplicar un tema JSON y un fondo sin deformación."], "lessons": [["Lienzo y retícula", "Configure una página personalizada de 1280 por 720 píxeles, relación 16:9. Reserve 32 píxeles a izquierda y derecha. Este ejercicio usa 16 píxeles entre tarjetas y 16 entre las dos gráficas. La retícula es una propuesta de práctica, no una regla universal."], ["Qué representan X y Y", "X es la posición horizontal desde el borde izquierdo; Y es la posición vertical desde el borde superior. En el lienzo Y crece hacia abajo. Se expresan en píxeles y no tienen relación con latitud y longitud. En Formato del objeto visual, General, Propiedades ajuste posición y tamaño; los nombres pueden variar entre versiones."], ["Coordenadas del ejercicio", "Encabezado: X32 Y24 ancho1216 alto72. Filtros: X32 Y112 ancho1216 alto56. Tarjetas: Y184 alto112 ancho292, con X32, X340, X648 y X956. Gráfica izquierda: X32 Y312 ancho800 alto376. Gráfica derecha: X848 Y312 ancho400 alto376. Todos los objetos quedan dentro del lienzo."], ["Tema y fondo", "El tema JSON define colores y otras opciones admitidas; no mueve los visuales. El fondo es una imagen estática; tampoco contiene filtros ni datos. Descargue Tema_DKRA.json e impórtelo mediante la opción de temas disponible en su versión. Puede recrear el fondo con formas nativas o usar el PNG descargable como fondo del lienzo."], ["Texto y acabado", "Use una familia tipográfica y jerarquía de tamaños. Alinee objetos y aplique distribución uniforme cuando corresponda. Separe títulos de datos y revise el contraste. Cree una disposición móvil adicional en lugar de asumir que la página de escritorio se adapta sola."]], "code": [["Tema JSON mínimo importable", "{\n  \"name\": \"DKRA Verde Ejecutivo\",\n  \"dataColors\": [\"#164D43\", \"#397DA8\", \"#B68127\", \"#9467A5\", \"#70857D\", \"#BC5C47\"],\n  \"background\": \"#F7F8F6\",\n  \"foreground\": \"#172C36\",\n  \"tableAccent\": \"#164D43\"\n}"]], "steps": ["Cree una página vacía y configure ancho 1280 y alto 720.", "Descargue Tema_DKRA.json e importe el tema. Compruebe que cambia colores, no posiciones.", "Reproduzca las zonas de la plantilla con formas nativas o establezca Fondo_DKRA_1280x720.png como fondo del lienzo con proporción conservada y transparencia adecuada.", "Agregue cuatro tarjetas y configure X, Y, ancho y alto con las coordenadas indicadas.", "Agregue dos visuales en la zona inferior. Ajuste sus fondos y transparencias para evitar recuadros superpuestos.", "Cambie deliberadamente X de la cuarta tarjeta a 1000: compruebe que 1000 + 292 excede 1280. Corrija el desbordamiento.", "Abra la disposición móvil y reorganice los objetos; contraste la legibilidad con la versión de escritorio."], "delivery": "Página diseñada y tabla de coordenadas de los objetos. Se evalúa precisión 40, consistencia 30 y lectura en escritorio y móvil 30.", "quiz": {"question": "Una tarjeta tiene X=956 y ancho=292. ¿Dónde queda su borde derecho?", "options": ["1248 píxeles", "292 píxeles", "956 píxeles"], "answer": 0, "explain": "El borde derecho es X más ancho. Con un lienzo de 1280 queda un margen de 32."}, "source": "https://learn.microsoft.com/power-bi/visuals/power-bi-visualization-format-pane-overview", "language": "json", "quizzes": [{"question": "Una tarjeta tiene X=956 y ancho=292. ¿Dónde queda su borde derecho?", "options": ["1248 píxeles", "292 píxeles", "956 píxeles"], "answer": 0, "explain": "El borde derecho es X más ancho. Con un lienzo de 1280 queda un margen de 32."}, {"question": "Aumentas Y de 184 a 220. ¿Qué ocurre en el lienzo?", "options": ["Se mueve a la izquierda", "El visual baja 36 píxeles", "Se convierte en latitud"], "answer": 1, "explain": "Y mide desplazamiento desde arriba; valores mayores ubican el objeto más abajo."}, {"question": "Importas un tema JSON y las tarjetas no se alinean. ¿Por qué?", "options": ["Faltan datos de ventas", "El tema solo funciona con mapas", "El tema no define por sí mismo la posición de los objetos"], "answer": 2, "explain": "La geometría del lienzo se configura aparte de la paleta y estilos del tema."}, {"question": "Un objeto X=1000, ancho=292 se coloca en una página de ancho1280. ¿Qué falla?", "options": ["Su borde derecho queda en1292 y excede12 píxeles", "Tiene demasiados filtros", "Le falta longitud geográfica"], "answer": 0, "explain": "Se comprueba el desbordamiento con X más ancho."}, {"question": "Duplicas una tarjeta y cambia su tamaño accidentalmente. ¿Dónde lo corriges con precisión?", "options": ["En la categoría de datos", "En Formato, General, Propiedades, tamaño y posición", "En la relación de tablas"], "answer": 1, "explain": "Las propiedades del objeto permiten fijar ancho, alto y posición."}, {"question": "El fondo se ve bien en escritorio. ¿Basta para asegurar lectura en móvil?", "options": ["Sí, el lienzo siempre se adapta", "Sí, si tiene cuatro tarjetas", "No: hay que revisar y configurar la disposición móvil"], "answer": 2, "explain": "El fondo no reorganiza automáticamente los visuales para otro tamaño de pantalla."}], "challenges": ["Coloca cuatro tarjetas con espacios exactamente iguales sin moverlas a ojo.", "Muestra un objeto fuera del lienzo y calcula cuánto se desborda.", "Importa el tema y demuestra qué propiedades cambian y cuáles no."], "resources": [["Tema JSON para Power BI", "descargas/Tema_DKRA.json"], ["Fondo PNG 1280 × 720", "descargas/Fondo_DKRA_1280x720.png"], ["Plantilla con zonas y coordenadas", "descargas/Plantilla_DKRA_Coordenadas.svg"]]}, {"id": 9, "title": "Configurar gráficas y controlar sus interacciones", "focus": "Practica ejes, leyendas, agregación, detalles, filtros y formato.", "goals": ["Asignar campos a los contenedores correctos.", "Evitar agregaciones y jerarquías automáticas no deseadas.", "Configurar interacciones entre objetos."], "lessons": [["Campos de un visual", "En barras, coloque Sucursal en el eje de categorías e Ingresos como valor. En líneas, use una fecha o mes con orden correcto. En dispersión, defina la unidad que representa cada punto mediante el campo de detalle o categoría que ofrezca su versión; sin ese campo puede aparecer un solo punto agregado."], ["Fechas y agregación", "Una jerarquía automática de fecha no es el mismo campo que la fecha sin jerarquía. Revise el nivel activo y si el eje es continuo o categórico. Sumar identificadores, promediar porcentajes o usar un mes de texto sin año son configuraciones que pueden producir un visual engañoso."], ["Interacciones", "Seleccione el visual de origen y use Editar interacciones para elegir si cada destino filtra, resalta o ignora la selección. La opción se aplica a la pareja origen y destino; no basta con revisar el gráfico que recibe la interacción."], ["Distribuciones", "Para un histograma, cree intervalos de una columna numérica y use conteo como frecuencia. El ancho de intervalo cambia la forma aparente. Las cajas y bigotes pueden requerir un visual adicional: si no está autorizado, describa sus componentes y use una alternativa nativa."], ["Formato y prueba", "Configure unidades, decimales, etiquetas y títulos; no use una escala distinta en cada pequeño múltiple sin declararlo. Compare el total del visual con una tabla de detalle y pruebe cómo responde al segmentador."]], "code": [["Medidas para dispersión", "Numero operaciones = COUNTROWS(Ventas)\n\nIngreso por operacion = DIVIDE([Ingresos], [Numero operaciones])"]], "steps": ["Construya barras de ingresos por sucursal y una línea mensual con DimFecha.", "Agregue una dispersión con un punto por sucursal, Ingresos en X y Margen en Y.", "Seleccione Norte en las barras y configure que la línea filtre, mientras una tarjeta permanezca sin interacción.", "Cree intervalos de Ingreso y un histograma con conteo; compare dos anchos de intervalo.", "Cambie un eje mensual de texto a orden por número o fecha y explique el efecto.", "Guarde dos capturas que muestren la misma selección con y sin interacción."], "delivery": "Página de cuatro visuales con tabla de campos y configuración de interacciones. Se evalúa campos 40, interacciones 35 y formato 25.", "quiz": {"question": "La dispersión muestra un único punto para cuatro sucursales. ¿Qué revisarías?", "options": ["El campo que define la categoría o detalle de cada punto", "El título del curso", "La carpeta de descargas"], "answer": 0, "explain": "Sin una categoría que distinga unidades, las medidas pueden agregarse en un solo punto."}, "source": "https://learn.microsoft.com/power-bi/create-reports/service-reports-visual-interactions", "language": "dax", "quizzes": [{"question": "La dispersión muestra un único punto para cuatro sucursales. ¿Qué revisarías?", "options": ["El campo que define la categoría o detalle de cada punto", "El título del curso", "La carpeta de descargas"], "answer": 0, "explain": "Sin una categoría que distinga unidades, las medidas pueden agregarse en un solo punto."}, {"question": "Quieres que una barra filtre una línea pero no una tarjeta. ¿Qué configuras?", "options": ["Una nueva tabla de fechas", "Editar interacciones desde el visual de origen hacia cada destino", "Un tema distinto"], "answer": 1, "explain": "La interacción se define por cada pareja de origen y destino."}, {"question": "Un histograma usa suma de ingresos como frecuencia. ¿Qué cambiarías para contar operaciones?", "options": ["El color", "La tipografía", "El agregado a conteo de observaciones por intervalo"], "answer": 2, "explain": "La frecuencia representa cuántas observaciones caen en cada intervalo."}, {"question": "Seleccionar una barra atenúa partes de otra gráfica. ¿Qué interacción podría estar activa?", "options": ["Resaltado", "Eliminación de filas", "Cambio de CRS"], "answer": 0, "explain": "El resaltado conserva el contexto del conjunto y destaca una parte, en visuales compatibles."}, {"question": "La fecha aparece como Año, Trimestre, Mes y Día sin haber creado esos campos. ¿Qué revisas?", "options": ["El separador decimal", "Si se insertó la jerarquía automática de fecha", "El tamaño del archivo ZIP"], "answer": 1, "explain": "Power BI puede ofrecer una jerarquía en lugar de la columna de fecha simple."}, {"question": "Cambias el ancho de intervalos y la distribución parece distinta. ¿Qué concluyes?", "options": ["Los datos necesariamente cambiaron", "El gráfico dejó de ser válido siempre", "La partición en intervalos afecta la representación"], "answer": 2, "explain": "Se debe declarar el ancho y evaluar sensibilidad antes de interpretar el patrón."}], "challenges": ["Produce un solo punto en dispersión y corrígelo agregando la categoría adecuada.", "Haz que un mismo clic filtre un visual y no afecte otro.", "Ordena correctamente meses de dos años sin usar orden alfabético."], "resources": []}, {"id": 10, "title": "Botones marcadores navegación y detalle", "focus": "Crea un panel de filtros que se abre sin borrar la selección del usuario.", "goals": ["Configurar marcadores y panel de selección.", "Distinguir navegación de página y marcador.", "Usar drillthrough e información emergente."], "lessons": [["Marcadores y selección", "El panel Selección controla visibilidad y orden de capas. Un marcador puede guardar estado de datos, visualización y página. Para abrir o cerrar un panel conservando filtros, configure los marcadores para capturar la visibilidad requerida y desactive Datos. Si necesita restablecer filtros, use un marcador distinto que sí capture ese estado."], ["Botones", "Una acción de botón puede navegar a una página, activar un marcador u ofrecer otras acciones. En modo de edición de Desktop, normalmente se prueba con Ctrl y clic. Si no funciona, revise acción habilitada, destino y si una forma transparente intercepta el clic."], ["Drillthrough", "Una página de detalle puede recibir filtros de un campo configurado para obtención de detalles. Ese campo debe estar disponible en el contexto de origen compatible. Añada un botón de regreso y revise si conserva filtros adicionales."], ["Información emergente", "Una página de tooltip presenta detalles al pasar el puntero. Configure su tipo y habilítela como información emergente, luego asígnela al visual compatible. Pruebe el contexto de filtro que recibe; no incluya información crítica accesible solo al pasar el ratón."]], "code": [["Título para la página de detalle", "Titulo detalle =\n\"Detalle | \" & SELECTEDVALUE(DimSucursal[Sucursal], \"Seleccione una sucursal\")"]], "steps": ["Cree un panel de filtros con una forma de fondo y dos segmentadores; agrúpelos en Selección.", "Cree los marcadores Abrir filtros y Cerrar filtros con Datos desactivado y alcance de visuales revisado.", "Asigne dos botones a esos marcadores y pruebe con Ctrl y clic en Desktop.", "Seleccione Sur y compruebe que cerrar y abrir el panel conserva la selección.", "Cree una página de detalle con DimSucursal[Sucursal] en el contenedor de drillthrough y un botón de regreso.", "Cree una página de información emergente y asígnela a una visual; pruebe dos sucursales distintas."], "delivery": "PBIX con panel desplegable, drillthrough y tooltip. Se evalúa conservación de filtros 40, navegación 35 y comprobaciones 25.", "quiz": {"question": "Al cerrar un panel de filtros vuelve la sucursal original. ¿Qué opción del marcador revisarías?", "options": ["Datos, que puede restaurar filtros capturados", "El color del botón", "El ancho del mapa"], "answer": 0, "explain": "Un marcador con estado de datos puede restablecer selecciones además de visibilidad."}, "source": "https://learn.microsoft.com/power-bi/create-reports/desktop-bookmarks", "language": "dax", "quizzes": [{"question": "Al cerrar un panel de filtros vuelve la sucursal original. ¿Qué opción del marcador revisarías?", "options": ["Datos, que puede restaurar filtros capturados", "El color del botón", "El ancho del mapa"], "answer": 0, "explain": "Un marcador con estado de datos puede restablecer selecciones además de visibilidad."}, {"question": "Un botón no navega al pulsarlo en modo edición de Desktop. ¿Qué prueba corresponde?", "options": ["Cambiar el archivo CSV", "Ctrl y clic, revisando acción y destino", "Cambiar la medida a columna"], "answer": 1, "explain": "En edición el clic simple puede seleccionar el objeto en vez de ejecutar la acción."}, {"question": "Una forma transparente cubre un botón. ¿Dónde revisarías el orden de capas?", "options": ["En la tabla de fechas", "En la configuración regional", "En el panel Selección"], "answer": 2, "explain": "Una capa encima puede interceptar la interacción aunque no se vea."}, {"question": "Quieres ir siempre a la página Mapa sin restaurar un estado de filtros. ¿Qué acción es más directa?", "options": ["Navegación de página", "Eliminar todas las relaciones", "Convertir latitud en texto"], "answer": 0, "explain": "Un destino de página es adecuado cuando no se necesita un estado de marcador."}, {"question": "La página de drillthrough no aparece desde un origen. ¿Qué compruebas?", "options": ["Que tenga un fondo verde", "El campo de drillthrough y el contexto disponible en el visual origen", "Que todos los títulos sean iguales"], "answer": 1, "explain": "La obtención de detalles depende de campos y contexto compatibles."}, {"question": "El tooltip muestra siempre el total de todas las sucursales. ¿Qué revisarías?", "options": ["Solo su tamaño de fuente", "El icono del botón", "El contexto que recibe y las medidas o relaciones que lo preservan"], "answer": 2, "explain": "Una medida que quita filtros o una asignación incorrecta puede impedir el detalle esperado."}], "challenges": ["Construye un marcador que restablezca filtros y otro que solo cambie visibilidad.", "Oculta un botón bajo una forma y diagnostica por qué dejó de responder.", "Prueba drillthrough desde dos sucursales y demuestra el contexto recibido."], "resources": []}, {"id": 11, "title": "Coordenadas geográficas y mapas en Power BI", "focus": "Carga latitud y longitud, corrige ubicaciones y construye un mapa con datos.", "goals": ["Distinguir grados decimales y coordenadas proyectadas.", "Categorizar y validar latitud y longitud.", "Relacionar ubicaciones y medidas sin duplicar ventas."], "lessons": [["Coordenadas geográficas", "Para la práctica use latitud y longitud en grados decimales WGS 84, EPSG:4326. Latitud va de −90 a 90 y longitud de −180 a 180. En los puntos mexicanos del ejercicio la latitud es positiva y la longitud negativa. No extrapole esa regla regional a todo el mundo."], ["Orden y separador", "En muchos datos GIS, X corresponde a longitud y Y a latitud; en los contenedores del visual arrastre cada campo por su nombre. Un archivo puede usar otro orden, por lo que debe verificarse su documentación. Grados decimales no son grados minutos segundos. Un valor decimal guardado como texto puede fallar por configuración regional."], ["UTM no es latitud y longitud", "Valores Este y Norte en metros no se vuelven grados al cambiar la categoría. Se requiere transformar desde el CRS real de origen, incluyendo zona, hemisferio y datum, hacia un CRS geográfico compatible. Si ya dispone de QGIS, exporte o reproyecte realmente la capa a EPSG:4326 y extraiga X e Y de la geometría transformada. Cambiar el CRS declarado o solo el del proyecto no transforma los números de las columnas."], ["Puntos y relaciones", "Coordenadas_Sucursales.csv contiene una ubicación ficticia por SucursalID y referencias aproximadas a ciudades. Combínelo con DimSucursal por su clave única. Al mantener una fila por sucursal, los puntos pueden mostrar sus Ingresos sin replicar los importes. Para varias ubicaciones por sucursal se necesita una granularidad y una asignación de hechos compatibles."], ["Configuración del mapa", "Convierta Latitud y Longitud a número decimal, establezca sus categorías de datos y revise la agregación. En Azure Maps use los contenedores Latitude y Longitude, la sucursal para diferenciar puntos y la medida Ingresos para tamaño cuando esté disponible. Revise conexión y habilitación por la organización si el visual no aparece."], ["Validación espacial", "Un rango numérico correcto no asegura una ubicación correcta. Un par invertido puede seguir dentro de los rangos globales. Revise signos, unidades, CRS, puntos de referencia y extensión esperada. El archivo de errores incluye casos deliberados para investigar; no los cargue como ubicaciones válidas."], ["Puntos y polígonos", "Una pareja de coordenadas representa un punto, no el límite de un estado, AGEB o parcela. Para polígonos necesita una geometría o una capa de referencia compatible y claves territoriales. El soporte de archivos y capas depende del visual y debe comprobarse en su documentación."]], "code": [["Columna de control en CoordenadasPrueba", "CoordenadaValida =\nVAR Lat = CoordenadasPrueba[Latitud]\nVAR Lon = CoordenadasPrueba[Longitud]\nRETURN IF(\n    ISBLANK(Lat) || ISBLANK(Lon),\n    \"Faltante\",\n    IF(Lat < -90 || Lat > 90 || Lon < -180 || Lon > 180,\n        \"Fuera de rango\", \"Revisar ubicacion\"\n    )\n)"]], "steps": ["Descargue el paquete Mapas y coordenadas. Las sucursales son ficticias y las referencias urbanas aproximadas.", "Cargue Coordenadas_Sucursales.csv y combine con DimSucursal usando SucursalID. Verifique cuatro filas antes y después.", "Asigne tipos decimales a Latitud y Longitud y las categorías de datos del mismo nombre.", "Agregue un Azure Maps compatible, coloque cada coordenada en su contenedor y agregue sucursal y medida de tamaño según las opciones disponibles.", "Compruebe que las cuatro referencias estén en México y que la suma de ingresos coincida con la tarjeta sin filtros.", "Cargue Coordenadas_Errores.csv como CoordenadasPrueba, sin relacionarla. Convierta las columnas numéricas que correspondan y agregue la columna de control.", "Investigue cada fila: rango, signo, par invertido, nulo, origen UTM y ubicación inesperada. El caso Mérida invertido puede pasar los rangos.", "Opcional: documente cómo transformaría una capa UTM conocida antes de exportar coordenadas; no aplique una conversión sin conocer el CRS."], "delivery": "Mapa de cuatro sucursales y bitácora de errores con corrección justificada. Se evalúa tipos y categorías 25, modelo 25, ubicación 30 y diagnóstico 20.", "quiz": {"question": "Recibes X=-102.29 e Y=21.88 de una fuente GIS que documenta orden X/Y geográfico. ¿Cómo los asignas?", "options": ["Latitud=-102.29 y Longitud=21.88", "Longitud=-102.29 y Latitud=21.88", "Ambos al tamaño de burbuja"], "answer": 1, "explain": "En ese orden documentado, X es longitud e Y latitud. No asuma el orden sin metadatos."}, "source": "https://learn.microsoft.com/azure/azure-maps/power-bi-visual-get-started", "language": "dax", "quizzes": [{"question": "Recibes X=-102.29 e Y=21.88 de una fuente GIS que documenta orden X/Y geográfico. ¿Cómo los asignas?", "options": ["Latitud=-102.29 y Longitud=21.88", "Longitud=-102.29 y Latitud=21.88", "Ambos al tamaño de burbuja"], "answer": 1, "explain": "En ese orden documentado, X es longitud e Y latitud. No asuma el orden sin metadatos."}, {"question": "Tienes Este=500000 y Norte=2420000 en UTM. ¿Basta categorizar como longitud y latitud?", "options": ["No: hay que transformar desde el CRS real a coordenadas geográficas", "Sí: las categorías convierten metros en grados", "Sí: se divide entre1000"], "answer": 0, "explain": "Categorizar una columna no transforma unidades ni proyección."}, {"question": "Un punto mexicano usa latitud21.88 y longitud+102.29. ¿Qué investigarías?", "options": ["La paleta", "El identificador del pedido", "El signo de longitud y el lugar esperado"], "answer": 2, "explain": "La referencia del ejercicio requiere longitud oeste negativa; un signo incorrecto desplaza el punto."}, {"question": "El par latitud=-89.59 y longitud=20.97 pasa los rangos globales, pero debía representar Mérida. ¿Qué demuestra?", "options": ["Que el punto está bien", "Que validar solo rangos no detecta todas las inversiones", "Que el CRS no importa"], "answer": 1, "explain": "Ambos números caben en los rangos, aunque el par invertido se ubique en otro lugar."}, {"question": "¿Qué representa una pareja de latitud y longitud?", "options": ["Un punto", "El límite completo de un municipio", "Una parcela con superficie"], "answer": 0, "explain": "Un polígono necesita geometría de límites y no se reconstruye a partir de un solo punto."}, {"question": "El mapa de ventas duplica importes tras combinar ubicaciones. ¿Qué revisarías?", "options": ["El zoom", "La leyenda", "La unicidad de SucursalID y la granularidad de la combinación"], "answer": 2, "explain": "Varias ubicaciones por clave pueden expandir y duplicar el hecho si no existe una asignación compatible."}], "challenges": ["Invierte una pareja que todavía pase los rangos y detecta el error por ubicación.", "Explica por qué cambiar la categoría de UTM no transforma las coordenadas.", "Combina dos ubicaciones para una clave y demuestra el riesgo de duplicación."], "resources": [["Mapas y coordenadas con errores de práctica", "descargas/Mapas_y_Coordenadas.zip"]]}, {"id": 12, "title": "Rendimiento publicación y proyecto en Power BI", "focus": "Prueba el informe antes de entregarlo y documenta sus configuraciones.", "goals": ["Medir tiempos por visual.", "Distinguir PBIX, publicación y permisos.", "Integrar un informe con navegación y mapa."], "lessons": [["Analizador de rendimiento", "Abra el Analizador de rendimiento disponible en Desktop, registre y actualice los visuales. Compare bajo las mismas selecciones y condiciones de caché. Diferencie consulta DAX, origen y renderizado cuando la herramienta lo permita."], ["Publicar no es conceder acceso", "Guardar un PBIX en una computadora no publica el informe. Publicar en el servicio tampoco concede automáticamente acceso a todos. Revise destino, modelo, credenciales, actualización y permisos según la licencia y configuración vigentes."], ["Seguridad y prueba", "Cree un rol de práctica que filtre Norte y pruebe Ver como. En el servicio, RLS se aplica bajo condiciones de acceso compatibles; permisos de edición elevados no quedan restringidos como un Viewer. No utilice Publicar en la web para restringir el acceso a información confidencial."], ["Proyecto final", "Integre modelo, DAX, tarjetas, gráficos, tema, posiciones X/Y, botones, mapa y una vista de atípicos. El resultado se evalúa por funcionamiento verificable, configuración reproducible y calidad del diseño, además de claridad al presentarlo."]], "code": [["Rol de práctica en DimSucursal", "// Expresion de filtro del rol, no una medida\nDimSucursal[Sucursal] = \"Norte\""]], "steps": ["Prepare un informe de tres páginas: Resumen, Mapa y Detalle.", "Incluya al menos diez medidas, cuatro tarjetas, dos gráficos y un panel de filtros desplegable.", "Aplique el tema y documente X, Y, ancho y alto de seis objetos.", "Muestre cuatro puntos con coordenadas validadas y agregue una tabla de revisión de atípicos.", "Pruebe segmentadores, interacciones, marcadores, navegación, tooltips y rol Norte.", "Registre tiempos de tres visuales y compruebe que una mejora conserva los resultados.", "Entregue el PBIX y una lista de pruebas. Si no dispone del servicio, documente la publicación propuesta sin realizarla."], "delivery": "Proyecto sobre 100: modelo y DAX 25, diseño 20, interacción 20, coordenadas y mapa 20, pruebas y rendimiento 15. Ponderación del curso: prácticas 40 %, retos de configuración 20 % y proyecto 40 %.", "quiz": {"question": "Publicaste un PBIX y otra persona no puede abrir el informe. ¿Qué falta revisar?", "options": ["El tipo de gráfico", "Acceso, permisos y condiciones de licencia del destino", "El nombre del archivo de colores"], "answer": 1, "explain": "Publicar y conceder acceso son operaciones diferentes."}, "source": "https://learn.microsoft.com/power-bi/create-reports/desktop-performance-analyzer", "language": "dax", "quizzes": [{"question": "Publicaste un PBIX y otra persona no puede abrir el informe. ¿Qué falta revisar?", "options": ["El tipo de gráfico", "Acceso, permisos y condiciones de licencia del destino", "El nombre del archivo de colores"], "answer": 1, "explain": "Publicar y conceder acceso son operaciones diferentes."}, {"question": "Quieres demostrar que una medida optimizada mejora el rendimiento. ¿Qué evidencia necesitas?", "options": ["Mismos resultados y tiempos comparados bajo condiciones equivalentes", "Solo que tenga menos letras", "Un color distinto"], "answer": 0, "explain": "La optimización debe conservar la semántica y medirse."}, {"question": "Un rol Norte funciona en Ver como. ¿Eso garantiza cualquier acceso en el servicio?", "options": ["Sí, sin excepciones", "Sí, si el usuario es administrador", "No: deben probarse también los permisos y condiciones reales de acceso"], "answer": 2, "explain": "Los roles elevados del espacio y otras condiciones pueden cambiar el alcance efectivo de RLS."}, {"question": "¿Publicar en la web es un mecanismo apropiado para restringir datos confidenciales?", "options": ["Sí, porque el vínculo es largo", "No: no sustituye acceso autenticado restringido", "Sí, si ocultas las páginas"], "answer": 1, "explain": "Un vínculo público o una página oculta no constituyen control de acceso."}, {"question": "El rendimiento mejora tras quitar un visual. ¿Qué compruebas además del tiempo?", "options": ["Que se conserve la funcionalidad y la información requerida", "Solo el número de colores", "Que cambie el total de ventas"], "answer": 0, "explain": "Una mejora no debe suprimir una función necesaria ni alterar resultados."}, {"question": "Mover el PBIX a otra carpeta provoca fallo de actualización de una ruta relativa o local dependiente. ¿Qué revisarías?", "options": ["La leyenda", "El estado de la autoevaluación", "La configuración de origen y los parámetros de ruta"], "answer": 2, "explain": "La carga debe poder localizar los archivos con la configuración de la nueva ubicación."}], "challenges": ["Optimiza un elemento, conserva controles y registra la evidencia de tiempos.", "Explica la diferencia entre guardar, publicar, compartir y actualizar.", "Entrega una lista de fallos provocados y las pruebas que demuestran su corrección."], "resources": []}];